"""Main orchestrator for running diagnostic checks."""

import platform
import sys
from typing import Optional

from .models import CheckResult, CheckStatus, DiagnosticReport


def _collect_system_info() -> dict:
    """Gather system information."""
    info = {
        "platform": platform.platform(),
        "python_version": sys.version,
        "python_executable": sys.executable,
        "architecture": platform.machine(),
    }
    try:
        from qbraid_core._version import __version__

        info["qbraid_core_version"] = __version__
    except Exception:
        info["qbraid_core_version"] = "unknown"

    try:
        import importlib.metadata

        info["qbraid_cli_version"] = importlib.metadata.version("qbraid-cli")
    except Exception:
        info["qbraid_cli_version"] = "not installed"

    try:
        from qbraid_core._build_info import BUILD_INFO

        if BUILD_INFO and BUILD_INFO.get("branch"):
            info["build_branch"] = str(BUILD_INFO["branch"])
            info["build_commit"] = str(BUILD_INFO.get("commit", ""))
    except Exception:
        pass

    return info


def run_diagnostics(
    categories: Optional[list[str]] = None,
    verbose: bool = False,
) -> DiagnosticReport:
    """Run diagnostic checks and return a report.

    Args:
        categories: List of categories to run. None = all applicable.
            Available: "auth", "config", "network", "jupyterlab", "environments", "system"
        verbose: If True, include extra details in check results.

    Returns:
        DiagnosticReport with all check results and system info.
    """
    from . import auth, config, environments, jupyterlab, network
    from . import system as sys_checks

    all_checkers = {
        "system": sys_checks.run_checks,
        "config": config.run_checks,
        "auth": auth.run_checks,
        "network": network.run_checks,
        "jupyterlab": jupyterlab.run_checks,
        "environments": environments.run_checks,
    }

    if categories:
        checkers = {k: v for k, v in all_checkers.items() if k in categories}
    else:
        checkers = all_checkers

    results: list[CheckResult] = []
    for category_name, checker_fn in checkers.items():
        try:
            category_results = checker_fn(verbose=verbose)
            results.extend(category_results)
        except Exception as exc:
            results.append(
                CheckResult(
                    name=f"{category_name}.runner",
                    category=category_name,
                    status=CheckStatus.ERROR,
                    message=f"Check runner crashed: {exc}",
                )
            )

    return DiagnosticReport(
        results=results,
        system_info=_collect_system_info(),
    )
